<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount,computed} from 'vue';
import LoadingClock from './LoadingClock.vue';
import fallbackThought from '../generated/loading-quote-fallback.json';
import {parseDailyThought,StartupReadingClock,type DailyThought} from '../domain/startup-loading';
import {telegram} from '../platform/telegram';
const props=withDefaults(defineProps<{ready:boolean;locale:string;minimumMs?:number;error?:string;beforeReveal?:()=>Promise<void>}>(),{minimumMs:2000,error:''});
const emit=defineEmits<{revealed:[];retry:[];failed:[unknown]}>();
const quote=ref<DailyThought|null>(null),progress=ref(0),foreground=ref(!document.hidden),leaving=ref(false);
const clock=new StartupReadingClock();const abort=new AbortController();let timer:ReturnType<typeof setTimeout>|undefined,revealTimer:ReturnType<typeof setTimeout>|undefined,frame=0,last=0,typingElapsed=0,disposed=false,preparing=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const text=computed(()=>quote.value?.[props.locale==='ru'?'ru':'en']??'');
const visibleText=computed(()=>Array.from(text.value).slice(0,Math.ceil(Array.from(text.value).length*progress.value)).join(''));
function activity(){foreground.value=!document.hidden&&telegram()?.isActive!==false;clock.setActive(foreground.value&&progress.value===1&&!props.error);last=0;tick();}
function schedule(){if(timer)clearTimeout(timer);if(disposed||!props.ready||props.error||!quote.value||progress.value<1||!foreground.value||leaving.value||preparing)return;const left=clock.remaining(props.minimumMs);if(left>0){timer=setTimeout(schedule,left+1);return;}preparing=true;void Promise.resolve(props.beforeReveal?.()).then(()=>{if(disposed)return;preparing=false;if(props.error)return;leaving.value=true;revealTimer=setTimeout(()=>{if(!disposed)emit('revealed');},reduced?0:650);}).catch(error=>{preparing=false;emit('failed',error);});}
function tick(stamp=performance.now()){
 if(frame)cancelAnimationFrame(frame);frame=0;
 if(disposed||!foreground.value||props.error||!quote.value)return;
 if(progress.value<1){if(last)typingElapsed+=Math.max(0,stamp-last);last=stamp;progress.value=reduced?1:Math.min(1,typingElapsed/1000);if(progress.value===1){clock.setActive(true);schedule();}else frame=requestAnimationFrame(tick);}
 schedule();
}
async function load(){
 try{quote.value=parseDailyThought(JSON.parse(localStorage.getItem('untouch_daily_thought_cache_v2')??'null')?.quote);}catch{}
 if(!quote.value)quote.value=parseDailyThought(fallbackThought);
 if(disposed)return;tick();
 // The current paragraph stays pinned. Network content is for the next launch.
 const api=import.meta.env.VITE_TELEGRAM_API_URL as string|undefined;
 if(api?.startsWith('https://'))void fetch(api.replace(/\/telegram-api\/?$/,'/loading-quote'),{signal:abort.signal,credentials:'omit',referrerPolicy:'no-referrer'}).then(r=>r.ok?r.json():null).then(r=>{const q=parseDailyThought(r?.quote);if(!q||r?.ok!==true||!/^\d{4}-\d{2}-\d{2}$/.test(r.day))return;try{const old=JSON.parse(localStorage.getItem('untouch_daily_thought_cache_v2')??'{}');if(typeof old.day==='string'&&old.day>r.day)return;localStorage.setItem('untouch_daily_thought_cache_v2',JSON.stringify({day:r.day,quote:q,revision:r.revision}));}catch{}}).catch(()=>{});
}
watch(()=>[props.ready,props.minimumMs],schedule);watch(()=>props.error,activity);
onMounted(()=>{document.addEventListener('visibilitychange',activity);telegram()?.onEvent('activated',activity);telegram()?.onEvent('deactivated',activity);void load();});
onBeforeUnmount(()=>{disposed=true;abort.abort();if(timer)clearTimeout(timer);if(revealTimer)clearTimeout(revealTimer);cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',activity);telegram()?.offEvent('activated',activity);telegram()?.offEvent('deactivated',activity);clock.setActive(false);});
</script>
<template>
 <div class="startup-scene" :class="{leaving}" role="status" :aria-label="locale==='ru'?'Загрузка игры':'Loading game'">
  <div class="startup-composition">
   <div class="thought-cloud"><span class="thought-label">{{locale==='ru'?'Мысль дня':'Thought of the day'}}</span><svg class="thought-tail" viewBox="0 0 32 14" aria-hidden="true"><path d="M31 .5 1 13 8 .5"/></svg><template v-if="!error"><span class="thought-measure" aria-hidden="true">{{text}}</span><p :aria-label="text">{{visibleText}}<span v-if="progress<1" class="typing-caret" aria-hidden="true">│</span></p></template><div v-else role="alert"><p>{{error}}</p><button class="primary" @click="emit('retry')">{{locale==='ru'?'Повторить':'Retry'}}</button></div></div>
   <div class="startup-art" :class="{paused:!foreground||!!error}"><img class="loading-hero" src="/assets/branding/ui/loading-hero-v1.webp" alt=""><LoadingClock :size="62" :active="foreground&&!error"/><span class="loading-dots" aria-hidden="true"><i></i><i></i><i></i></span><img class="loading-logo" src="/assets/branding/ui/loading-logo-v1.webp" alt="Untouch"></div>
  </div>
 </div>
</template>
